#!/usr/bin/env python3
import argparse,pathlib,json,hashlib,datetime
ap=argparse.ArgumentParser(); ap.add_argument('--root',default='.'); ap.add_argument('--out',default='artifact_inventory.md'); ap.add_argument('--json',default='artifact_inventory.json'); a=ap.parse_args(); root=pathlib.Path(a.root); files=[p for p in root.rglob('*') if p.is_file() and '.git' not in p.parts]
summary={'generated_at_utc':datetime.datetime.utcnow().replace(microsecond=0).isoformat()+'Z','total_files':len(files),'prompt_files':len(list((root/'prompt-system/prompts').glob('*.md'))),'plugin_skills':len(list((root/'plugin/crafting-system/skills').glob('*/SKILL.md'))),'plugin_agents':len(list((root/'plugin/crafting-system/agents').glob('*.md'))),'hook_scripts':len(list((root/'plugin/crafting-system/hooks').glob('*.sh'))),'shell_scripts':len(list(root.rglob('*.sh'))),'yaml_files':len(list(root.rglob('*.yaml')))+len(list(root.rglob('*.yml'))),'json_files':len(list(root.rglob('*.json')))}
(root/a.json).write_text(json.dumps({'summary':summary},indent=2)); (root/a.out).write_text('# Artifact Inventory\n\n'+'\n'.join(f'- {k}: {v}' for k,v in summary.items())+'\n'); print(json.dumps(summary))
